import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Tag Reference","description":"","frontmatter":{},"headers":[],"relativePath":"tags/tag.md","filePath":"tags/tag.md","lastUpdated":0}`),a={name:`tags/tag.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="tag-reference" tabindex="-1">Tag Reference <a class="header-anchor" href="#tag-reference" aria-label="Permalink to “Tag Reference”">​</a></h1><h2 id="the-concept-of-a-tag" tabindex="-1">The concept of a tag <a class="header-anchor" href="#the-concept-of-a-tag" aria-label="Permalink to “The concept of a tag”">​</a></h2><p>In JNTemplate, a tag refers specifically to a syntax block that contains template code. It is the basic rendering unit: once template parsing is complete, that syntax block is replaced by concrete data or content.</p><h2 id="tag-categories" tabindex="-1">Tag categories <a class="header-anchor" href="#tag-categories" aria-label="Permalink to “Tag categories”">​</a></h2><p><strong>By the way they are written, tags fall into two kinds: full tags and shorthand tags</strong> (tag prefixes and suffixes are configurable; this document uses the default configuration):</p><ul><li>Full tag: starts with <code>\${</code> and ends with <code>}</code>, for example <code>\${tagName}</code></li><li>Shorthand tag: starts with <code>$</code> and ends at a whitespace character, for example <code>$tagName</code></li></ul><p>Normally, the vast majority of tags can use the shorthand form, which looks cleaner. However, shorthand tags cannot be used in the following cases:</p><ol><li>Arithmetic expressions and logical expressions must use full tags, e.g. <code>\${3+5}</code> cannot be shortened to <code>$3 + 5</code>.</li><li>When the tag is followed by a period, a letter or a digit, a full tag must be used. For example <code>\${siteHost}</code>.com cannot be shortened to <code>$siteHost.com</code>.</li><li>When whitespace or other characters that require a full tag appear after the tag.</li></ol><p><strong>By type, tags fall into basic tags and complex tags.</strong></p><ul><li>Basic tag: all code is contained between the tag prefix <code>\${</code> and the tag suffix <code>}</code>. Basic tags are further divided into ordinary basic tags, special tags and child tags. <ul><li>Ordinary tag: a plain basic tag.</li><li>Special tag: generally has a special meaning, equivalent to a system keyword in a programming language.</li><li>Child tag: a tag that has a parent tag, where the parent is usually another basic tag.</li></ul></li><li>Complex tag: composed of one or more basic tags.</li></ul><h2 id="tag-relationships" tabindex="-1">Tag relationships <a class="header-anchor" href="#tag-relationships" aria-label="Permalink to “Tag relationships”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.</span></span>
<span class="line"><span>└── Tag</span></span>
<span class="line"><span>    ├── Complex tag</span></span>
<span class="line"><span>    └── Basic tag</span></span>
<span class="line"><span>        ├── Ordinary tag</span></span>
<span class="line"><span>        ├── Special tag</span></span>
<span class="line"><span>        └── Child tag</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>All examples in this document use the default parameters; exceptions are called out explicitly.</p></div>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};